{% extends "base.html" %}
{% block title %}Edit bag · registry.coffee{% endblock %}
{% block main %}
  <div class="top"><a class="back" href="{{ back[0] }}">‹ {{ back[1] }}</a></div>
  <h1 class="serif title mt8">Edit bag</h1>
  <p class="body">Saving keeps its shots as they were.</p>
  <form class="fill" id="bagedit" data-next="{{ back[0] }}" novalidate>
    <label class="flabel" for="coffee">Roaster and coffee</label>
    <input class="input" id="coffee" name="coffee_freetext" autocomplete="off" value="{{ bag.coffee_freetext or '' }}" required>
    <p class="meta mt8" data-match>{% if bag.coffee_id %}Matched to the catalog: {{ name }}{% else %}Not matched to the catalog{% endif %}</p>
    <button class="btn text start" type="button" data-search-open>Search catalog</button>
    <div data-search hidden>
      <label class="flabel" for="catalog-query">Search by roaster or coffee</label>
      <input class="input" id="catalog-query" type="search" autocomplete="off" maxlength="120">
      <button class="btn text start" type="button" data-search-submit>Search</button>
      <p class="meta" data-search-status role="status"></p>
      <div class="rows" data-search-results></div>
    </div>
    <label class="flabel" for="roast_date">Roast date (optional)</label>
    <input class="input" id="roast_date" name="roast_date" type="date" max="{{ now.date().isoformat() }}" value="{{ bag.roast_date.isoformat() if bag.roast_date else '' }}" data-empty-class>
    <label class="flabel" for="weight_g">Weight in grams (optional)</label>
    <input class="input" id="weight_g" name="weight_g" inputmode="numeric" autocomplete="off" value="{{ bag.weight_g or '' }}">
    <div class="seg two mt24" role="group" aria-label="This bag" data-finished>
      <button type="button" data-v="false" aria-pressed="{{ 'false' if bag.finished_on else 'true' }}">Still using it</button><button type="button" data-v="true" aria-pressed="{{ 'true' if bag.finished_on else 'false' }}">Finished</button>
    </div>
    <div class="hint" data-hint role="status"></div>
    <div class="spacer"></div>
    <div class="dock sticky"><button class="btn primary" type="submit">Save bag</button></div>
  </form>
  <script id="bag-record" type="application/json">{{ record | tojson }}</script>
{% endblock %}
{% extends "base.html" %}
{% from "_macros.html" import nav, shotrow %}
{% block title %}{{ name }} · registry.coffee{% endblock %}
{% block main %}
  <div class="top"><a class="back" href="/coffees">‹ Coffees</a>
    {% if siblings | length > 1 %}<span class="meta">Bag {{ index }} of {{ siblings | length }}{% if index > 1 %} <a class="ext tap" href="/coffee/{{ siblings[index - 2].bag_id }}">‹ earlier</a>{% endif %}{% if index < siblings | length %} <a class="ext tap" href="/coffee/{{ siblings[index].bag_id }}">later ›</a>{% endif %}</span>{% endif %}</div>
  {% if bag.photo_id %}<img class="cover mt8" src="/photos/{{ bag.photo_id }}" alt="The bag" width="358" height="179" fetchpriority="high">{% endif %}
  <h1 class="serif title mt16">{{ name }}</h1>
  <div class="body">{{ facts }}</div>
  <div class="row"><span class="meta">
    {%- if bag.roast_date %}Roasted {{ bag.roast_date.strftime("%b ") ~ bag.roast_date.day }} · day {{ days_off }}{% endif %}
    {%- if bag.roast_date and bag.finished_on %} · {% endif %}
    {%- if bag.finished_on %}{{ "finished" if bag.roast_date else "Finished" }} {{ bag.finished_on.strftime("%b ") ~ bag.finished_on.day }}{% endif -%}
  </span><a class="ext tap" href="/bag/{{ bag.bag_id }}/edit">Edit bag</a></div>

  {% if best %}
  {% set gr = grinder_of(best) %}
  <h2 class="section">Best so far · rated {{ best.rating }}, {{ date(best.brewed_at) }}{% if gr %} · {{ gr.name }}{% endif %}</h2>
  <div class="best">
    <div><span class="label">Dose</span><span class="num n34">{{ g(best.dose_g, 1) }}<span class="u"> g</span></span></div>
    <div><span class="label">Yield</span><span class="num n34">{{ g(best.yield_g, 1) }}<span class="u"> g</span></span></div>
    <div><span class="label">Time</span><span class="num n34">{{ g(best.time_s) }}<span class="u"> s</span></span></div>
    <div><span class="label">Grind</span><span class="num n34">{{ g(best.grinder_setting) }}</span></div>
  </div>
  <h2 class="section">All {{ shots_n(n_all) }}</h2>
  <div>{{ chart | safe }}</div>
  <div class="legend mt8" aria-hidden="true">{% for t, l in (("sour", "Sour"), ("balanced", "Balanced"), ("bitter", "Bitter"), ("none", "No taste")) if t in tastes %}<span class="key {{ t }}">{{ l }}</span>{% endfor %}</div>
  {% else %}
  <p class="body mt24 ruled">No shots of this coffee yet.</p>
  {% endif %}

  {% if shots %}
  <h2 class="section">This bag</h2>
  <div class="list">{% for s in shots[:5] %}{{ shotrow(s, day) }}{% endfor %}</div>
  {% if shots | length > 5 %}
  <details class="disclose"><summary class="btn text start">All {{ shots_n(shots | length) }}</summary>
    <div class="list">{% for s in shots[5:] %}{{ shotrow(s, day) }}{% endfor %}</div>
  </details>
  {% endif %}
  {% endif %}

  {% if catalog %}
  <h2 class="section">From the catalog</h2>
  <dl class="spec">
    {% if catalog.origin %}<dt>Origin</dt><dd>{{ catalog.origin }}</dd>{% endif %}
    {% if raw.elevation_masl_min %}<dt>Elevation</dt><dd>{{ "{:,}".format(raw.elevation_masl_min | int) }}{% if raw.elevation_masl_max and raw.elevation_masl_max != raw.elevation_masl_min %}–{{ "{:,}".format(raw.elevation_masl_max | int) }}{% endif %} m</dd>{% endif %}
    {% if catalog.notes %}<dt>Notes</dt><dd>{{ catalog.notes }}</dd>{% endif %}
    {% if catalog.price %}<dt>Price</dt><dd>{{ catalog.price }}</dd>{% endif %}
    {% if catalog.in_stock is not none %}<dt>Stock</dt><dd>{{ "In stock" if catalog.in_stock else "Sold out" }}</dd>{% endif %}
    {% if raw.url and raw.url.startswith(("https://", "http://")) %}<dt>Shop</dt><dd><a class="ext" href="{{ raw.url }}" rel="noopener noreferrer" target="_blank">{{ raw.url.split("/")[2] }}</a></dd>{% endif %}
  </dl>
  {% endif %}
  <div class="mt24"></div>
{% endblock %}
{% block nav %}{{ nav('coffees') }}{% endblock %}
{% extends "base.html" %}
{% from "_macros.html" import synced, taste, nav, shotrow %}
{% block main %}
  {% set last = shots[-1] if shots else None %}
  <div class="top"><span class="meta">{{ now.strftime("%A, %B ") ~ now.day }}</span>{{ synced() }}</div>
  <section class="mt8">
    <div class="label">{{ "On the grinder" if p.bag else "Last coffee" }}</div>
    <h1 class="serif name mt4">{% if p.bag %}<a href="/coffee/{{ p.bag.bag_id }}">{{ name }}</a>{% else %}{{ name }}{% endif %}</h1>
    <div class="meta mt4">{{ facts }}</div>
    {% if open_bags | length > 1 %}<a class="ext tap" href="/bags/switch">Switch coffee</a>{% endif %}
    {% if p.bag %}<div class="row"><span class="meta">{% if p.bag.roast_date %}Roasted {{ p.bag.roast_date.strftime("%b ") ~ p.bag.roast_date.day }} · day {{ days_off }} · {% endif %}{{ shots_n(shots | length) }}</span><a class="ext tap" href="/bag/{{ p.bag.bag_id }}/edit?from=today">Edit bag</a></div>{% endif %}
  </section>
  {% if last %}
  <section class="mt24 ruled">
    <div class="row"><span class="label">Last shot, {{ when(last.brewed_at) }}</span>{{ taste(last.taste) }}</div>
    <div class="row end mt8">
      <span class="num n44">{{ g(last.dose_g, 1) }} → {{ g(last.yield_g, 1) }}<span class="u"> g</span></span><span class="num n44">{{ g(last.time_s) }}<span class="u"> s</span></span>
    </div>
    {% set gr = grinder_of(last) %}
    <div class="meta mt8">Grind {{ g(last.grinder_setting) }}{% if gr %} on {{ gr.name }}{% endif %} · 1:{{ "%.2f" | format(ratio(last)) }} · rated {{ last.rating }}</div>
    <div class="mt16">{{ target | safe }}</div>
    <p class="serif advice mt12">{{ summary }}</p>
  </section>
  {% if earlier %}
  <div class="section">Earlier with this {{ "bag" if p.bag else "coffee" }}</div>
  <div class="list">
    {% for s in earlier %}{{ shotrow(s, day, "?from=today") }}{% endfor %}
  </div>
  {% endif %}
  {% else %}
  <p class="body mt24 ruled">No shots of this bag yet.</p>
  {% endif %}
  <div class="spacer"></div>
  <div class="dock">
    <a class="btn primary" href="/log">{% if p.last %}Pull again <span class="sub">{{ g(p.dose_g, 1) }} → {{ g(p.yield_g, 1) }} g · grind {{ g(p.grinder_setting) }}</span>{% else %}Log a shot{% endif %}</a>
    <a class="btn text" href="/bag/new">New bag</a>
  </div>
{% endblock %}
{% block nav %}{{ nav('today') }}{% endblock %}
{% extends "base.html" %}
{% from "_macros.html" import chevron %}
{% block title %}Log shot · registry.coffee{% endblock %}
{% block main %}
  {% set gr, bk, last = p.grinder, p.basket, p.last %}
  <div data-online-only>
  <div class="top">{% if fixing %}<a class="back" href="/shot/{{ fixing.shot_id }}">‹ Shot</a>{% else %}<a class="back" href="/">‹ Today</a>{% endif %}{% if fixing %}<span class="meta">{{ gr.name }} · {{ bk.name }}</span>{% else %}<a class="chip quiet" href="/log/gear?grinder={{ gr.equipment_id }}&amp;basket={{ bk.equipment_id }}{% if p.machine %}&amp;machine={{ p.machine.equipment_id }}{% endif %}" aria-label="Grinder and basket: {{ gr.name }}, {{ bk.name }}. Change">{{ gr.name }} · {{ bk.name }}</a>{% endif %}</div>
  <div class="row base mt8">
    <h1 class="serif name">{{ name }}</h1>
    <div class="label">Ratio <span class="num n24 ink" data-ratio></span></div>
  </div>
  {% if fixing %}<div class="meta mt4">Correcting the {{ fixing_when }} shot. The original stays in history.</div>
  {% if bag_lines | length > 1 %}<h2 class="section">This bag</h2>
  <div class="rows">
    {% for l in bag_lines %}
    <a class="bagrow" href="/log?correct={{ fixing.shot_id }}&amp;bag={{ l.bag.bag_id }}"{% if fixing_bag and fixing_bag.bag_id == l.bag.bag_id %} aria-current="true"{% endif %}>
      {% if l.bag.photo_id %}<img class="thumb" src="/photos/{{ l.bag.photo_id }}" alt="" width="56" height="56" loading="lazy" decoding="async">{% endif %}
      <span class="grow"><span class="n">{{ l.name }}</span><span class="meta">{{ l.facts }}</span></span>
      {{ chevron() }}
    </a>
    {% endfor %}
  </div>{% endif %}
  {% else %}<div class="meta mt4">{% if last %}Last shot {{ g(last.time_s) }} s{% if last.taste %} · {{ last.taste }}{% endif %} · rated {{ last.rating }}{% else %}First shot of this {{ "bag" if p.bag else "coffee" }}{% endif %} · {% if p.water_temp_c %}{{ g(p.water_temp_c) }} °C, {% endif %}{{ p.brew_method }}{{ ", milk drink" if p.is_milk_drink }}</div>{% endif %}
  </div>
  <section class="fill" data-offline-saved data-name="{{ name }}" data-grinder="{{ gr.name }}" hidden>
    <div class="top"><h1 class="meta" tabindex="-1" data-o="title">Saved on this phone · {{ name }}</h1><span class="synced" data-sync>1 waiting to sync</span></div>
    <div class="label mt16">Ratio</div>
    <div class="num n112 mt4" data-o="ratio"></div>
    <div class="row end mt16">
      <span class="num n34"><span data-o="dose"></span><span class="u"> g</span></span><span class="num n34"><span data-o="time"></span><span class="u"> s</span></span>
    </div>
    <div class="row mt8"><span class="meta" data-o="grind"></span><span data-o="taste"></span></div>
    <div class="section">Compared with the last shot</div>
    <p class="body" data-o="summary">Shows once the shot syncs.</p>
    <div class="spacer"></div>
    <div class="dock">
      <div class="undo" data-unqueue><span>Shot saved</span><button type="button">Undo<i></i></button></div>
      <a class="btn primary" href="/">Done</a>
    </div>
  </section>
  <form id="shot" novalidate>
    <div class="field">
      <div><label class="l label" for="dose_g">Dose</label><span class="num n56"><input id="dose_g" inputmode="decimal" data-step="0.1" data-min="5" data-max="30" data-digits="1"><span class="u"> g</span></span></div>
      <div class="steps"><button type="button" class="step" data-for="dose_g" data-dir="-1" aria-label="Less dose">−</button><button type="button" class="step" data-for="dose_g" data-dir="1" aria-label="More dose">+</button></div>
    </div>
    <div class="field">
      <div><label class="l label" for="yield_g">Yield</label><span class="num n56"><input id="yield_g" inputmode="decimal" data-step="0.1" data-min="5" data-max="500" data-digits="1"><span class="u"> g</span></span></div>
      <div class="steps"><button type="button" class="step" data-for="yield_g" data-dir="-1" aria-label="Less yield">−</button><button type="button" class="step" data-for="yield_g" data-dir="1" aria-label="More yield">+</button></div>
    </div>
    <div class="field">
      <div><label class="l label" for="time_s">Time</label>
        <span class="num n56" data-timed{% if not fixing %} hidden{% endif %}><input id="time_s" inputmode="numeric" data-step="1" data-min="1" data-max="600"><span class="u"> s</span></span>
        <span class="num n24 notimed" data-untimed{% if fixing %} hidden{% endif %}>Not timed{% if last %}<span class="u"> · last {{ g(last.time_s) }} s</span>{% endif %}</span></div>
      <div class="steps">{% if fixing %}<button type="button" class="step" data-for="time_s" data-dir="-1" aria-label="Less time">−</button><button type="button" class="step" data-for="time_s" data-dir="1" aria-label="More time">+</button>{% else %}<button type="button" class="step wide" data-timer>Start</button><button type="button" class="step type" data-type>Type</button>{% endif %}</div>
    </div>
    <div class="field">
      <div><label class="l label" for="grinder_setting">Grind</label><span class="num n56"><input id="grinder_setting" inputmode="decimal" data-step="{{ g(gr.scale_step) }}" data-min="{{ g(gr.scale_min) }}" data-max="{{ g(gr.scale_max) }}"><span class="u"> of {{ g(gr.scale_max) }}</span></span></div>
      <div class="steps"><button type="button" class="step" data-for="grinder_setting" data-dir="-1" aria-label="Lower grind number">−</button><button type="button" class="step" data-for="grinder_setting" data-dir="1" aria-label="Higher grind number">+</button></div>
    </div>
    <div class="row mt16 minh44"><span class="label" id="taste-l">Taste</span>
      {% if last and not fixing %}<button type="button" class="chip" data-same aria-pressed="false">Same as last <b>· {{ (last.taste or "no taste") | capitalize }}, {{ last.rating }}</b></button>{% endif %}</div>
    <div class="seg mt8" role="group" aria-labelledby="taste-l" data-taste>
      <button type="button" data-v="sour" aria-pressed="false">Sour</button><button type="button" data-v="balanced" aria-pressed="false">Balanced</button><button type="button" data-v="bitter" aria-pressed="false">Bitter</button>
    </div>
    <div class="label mt16" id="rating-l">Rating</div>
    <div class="pips mt8" role="group" aria-labelledby="rating-l" data-rating>
      {% for i in range(1, 6) %}<button type="button" data-v="{{ i }}" aria-pressed="false">{{ i }}</button>{% endfor %}
    </div>
    <div class="anchors"><span>worst</span><span>best</span></div>
    <details class="disclose mt8"{% if fixing and (fixing.notes or fixing.water_temp_c) %} open{% endif %}>
      <summary class="link"><span>More<span class="meta" data-more-summary></span></span><svg viewBox="0 0 8 14" aria-hidden="true"><path d="M1 1l6 6-6 6" fill="none" stroke="currentColor" stroke-width="1.75"/></svg></summary>
      <div class="grid2 mt8">
        <div><label class="flabel" for="water_temp_c">Water (°C)</label><input class="input" id="water_temp_c" inputmode="decimal" autocomplete="off" placeholder="Not recorded"></div>
        <div><span class="flabel" id="milk-l">Milk</span>
          <div class="seg two" role="group" aria-labelledby="milk-l" data-milk>
            <button type="button" data-v="false" aria-pressed="true">No</button><button type="button" data-v="true" aria-pressed="false">Yes</button>
          </div></div>
      </div>
      <label class="flabel" for="notes">Notes</label>
      <textarea class="input area" id="notes" rows="3" maxlength="2000" placeholder="e.g. new bag, puck was wet"></textarea>
    </details>
    <div class="hint" data-hint role="status"></div>
    <div class="spacer"></div>
    <div class="dock sticky"><button class="btn primary" type="submit" data-save>{{ "Save correction" if fixing else "Save shot" }}</button></div>
  </form>
  <script id="prefill" type="application/json">{{ form | tojson }}</script>
{% endblock %}
{% extends "base.html" %}
{% from "_macros.html" import nav, chevron %}
{% block title %}Switch coffee · registry.coffee{% endblock %}
{% block main %}
  <div class="top"><a class="back" href="/">‹ Today</a></div>
  <h1 class="serif title mt8">Switch coffee</h1>
  <p class="body">Choose the open bag you’re pulling now.</p>
  <div class="rows mt16">
    {% for l in lines %}
    <a class="bagrow" href="/bag/{{ l.bag.bag_id }}/use" data-select-bag="{{ l.bag.bag_id }}"{% if selected and selected.bag_id == l.bag.bag_id %} aria-current="true"{% endif %}>
      {% if l.bag.photo_id %}<img class="thumb" src="/photos/{{ l.bag.photo_id }}" alt="" width="56" height="56" loading="lazy" decoding="async">{% endif %}
      <span class="grow"><span class="n">{{ l.name }}</span><span class="meta">{{ l.facts }}{% if selected and selected.bag_id == l.bag.bag_id %} · on the grinder{% endif %}</span></span>
      {{ chevron() }}
    </a>
    {% endfor %}
  </div>
{% endblock %}
{% block nav %}{{ nav('today') }}{% endblock %}
{% extends "base.html" %}
{% from "_macros.html" import nav, chevron %}
{% block title %}Coffees · registry.coffee{% endblock %}
{% block main %}
  <h1 class="serif title mt16">Coffees</h1>
  {% if lines %}
  <p class="body">Every bag you’ve opened, the one in use first.</p>
  <div class="rows mt16">
    {% for l in lines %}
    <a class="bagrow" href="/coffee/{{ l.bag.bag_id }}">
      {% if l.bag.photo_id %}<img class="thumb" src="/photos/{{ l.bag.photo_id }}" alt="" width="56" height="56" loading="lazy" decoding="async">{% endif %}
      <span class="grow"><span class="n">{{ l.name }}</span>
        <span class="meta">{{ l.facts }}</span>
        <span class="meta">{{ shots_n(l.shots | length) }}{% if l.best %} · best rated {{ l.best.rating }}, {{ date(l.best.brewed_at) }}{% endif %}{% if l.bag.finished_on %} · finished{% endif %}</span></span>
      {{ chevron() }}
    </a>
    {% endfor %}
  </div>
  {% else %}
  <p class="body">No bags yet. Each bag you open shows up here with its shots and its best one so far.</p>
  {% endif %}
  {% if loose %}<p class="meta mt16">{{ shots_n(loose | length) }} from before bags were recorded are in History.</p>{% endif %}
  {% if lines or loose %}
  <h2 class="section">All shots</h2>
  <a class="link ruled" href="/history"><span>History<span class="meta">Every shot, by bag</span></span>{{ chevron() }}</a>
  {% endif %}
  {% if not lines %}<div class="spacer"></div><div class="dock"><a class="btn primary" href="/bag/new">New bag</a></div>
  {% else %}<div class="mt24"></div>{% endif %}
{% endblock %}
{% block nav %}{{ nav('coffees') }}{% endblock %}

