function finishBag(b) {
  const id = b.dataset.finishBag;
  b.addEventListener("click", async () => {
    b.disabled = true;
    const now = new Date();
    const today = `${now.getFullYear()}-${String(now.getMonth() + 1).padStart(2, "0")}-${String(now.getDate()).padStart(2, "0")}`;
    try {
      await send(`finish:${id}`, `/api/bags/${id}/finish`, { finished_on: today });
      tick();
      go(location.pathname, `Bag finished: ${b.dataset.name}`);
    } catch (err) {
      if (!(err instanceof Rejected)) return go(location.pathname, `Bag finished on this phone: ${b.dataset.name}. It’ll sync when you’re back online.`);
      document.querySelector("[data-finish-hint]").textContent = err.message;
      b.disabled = false;
    }
  });
}

